pages.hostile/01-recursion:
// unbounded recursion: OpenSCAD's own stack guard ends it
function f(n) = f(n + 1) + 1;
echo(f(0));
module m(n) { m(n + 1); }
m(0);

pages.hostile/02-slow:
// a tail call that runs for about 15 s: the time limit stops it
function f(n, a = 0) = n == 0 ? a : f(n - 1, a + 1);
echo(f(50000000));
cube(1);

pages.hostile/05-include-self:
// a page that includes itself, twice over
include <05-include-self.scad>
use <./05-include-self>
cube(3);

